def parse_block_spoiler(block: 'BlockParser', m: Match[str], state:
    'BlockState') ->int:
    text = m.group(0)
    text = _BLOCK_SPOILER_START.sub('', text)
    children = block.parse(text, state.env)
    token = {'type': 'block_spoiler', 'children': children}
    state.append_token(token)
    return m.end()


def render_block_spoiler(renderer: 'BaseRenderer', text: str) ->str:
    return '<div class="spoiler">\n' + text + '</div>\n'


def spoiler(md: 'Markdown') ->None:
    md.block.register(
        'block_spoiler',
        r'^( {0,3}![^\n]*\n)+',
        parse_block_spoiler,
        before='paragraph',
    )
    md.inline.register(
        'inline_spoiler',
        INLINE_SPOILER_PATTERN,
        parse_inline_spoiler,
        before='link',
    )
    if md.renderer:
        md.renderer.register('block_spoiler', render_block_spoiler)
        md.renderer.register('inline_spoiler', render_inline_spoiler)
